input.sparql:
SELECT ?node ?name WHERE {
  ?node a brick:Zone ; brick:hasSubclass* .
  OPTIONAL { ?node rdfs:label ?name }
  FILTER (contains(str(?node), "Perimeter_bot_ZN_3"))
}

PREFIX brick: <http://brickschema.org/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?node ?label WHERE {
  OPTIONAL { ?node rdfs:label ?label }
  FILTER (regex(str(?node), "Perimeter_bot_ZN_3"))
} LIMIT 20

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?node ?label WHERE {
  ?node rdfs:label ?label .
  FILTER (regex(?label, "Perimeter_bot_ZN_3"))
} LIMIT 20

PREFIX brick: <http://brickschema.org/Brick#>
PREFIX ref: <http://example.org/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?point ?pc ?ts WHERE {
  ?point brick:isLocationOf? ?zone .
} LIMIT 20

PREFIX brick: <http://brickschema.org/Brick#>
PREFIX ref: <http://example.org/ref#>
SELECT ?point ?ts WHERE {
  ?point brick:hasProperty ?zone .
} LIMIT 5

PREFIX brick: <http://brickschema.org/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?point ?class ?tsid WHERE {
  ?point brick:isPointOf <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z02> .
  ?point a ?class .
  OPTIONAL { ?point ref:hasExternalReference ?refNode ; ref:hasTimeseriesId ?tsid }
} LIMIT 40

PREFIX brick: <http://brickschema.org/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?point ?class WHERE {
  ?point brick:isPointOf <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z02> .
  ?point a ?class .
} LIMIT 40

PREFIX brick: <http://brickschema.org/Brick#>
SELECT ?point ?class WHERE {
  ?point a brick:Occupancy_Sensor .
  OPTIONAL { ?point brick:isPointOf ?z }
  ?point a ?class .
} LIMIT 40

